function circuit(){return `<svg class="mini-circuit" viewBox="0 0 260 115" role="img" aria-label="A voltage source, resistor and capacitor in series"><g fill="none" stroke="currentColor" stroke-width="1.5" style="color:#668773"><path d="M40 43V24h50l5-6 7 12 7-12 7 12 7-12 7 12 5-6h63v33M198 68v27H40V70"/><circle cx="40" cy="56" r="14"/><path d="M35 52h10M40 47v10M36 61h8M184 58h28M184 67h28"/></g><text x="107" y="10">R</text><text x="219" y="66">C</text><text x="10" y="60">Vₛ</text><text x="110" y="86">V꜀(t)</text><circle cx="198" cy="40" r="2.5" fill="#668773"/></svg>`}
function filtered(){return filterProblems({problems,progress:saved,filters:libraryFilters(),view:view==='saved'?'saved':'problems',recommend:list=>practice.recommended(list)});}
function tableRows(){const list=filtered();return list.length?`<div class="table-wrap"><table class="problem-table"><thead><tr><th aria-label="Status"></th><th>PROBLEM</th><th>DIFFICULTY</th><th>TIME</th><th aria-label="Save"></th></tr></thead><tbody>${list.map(p=>`<tr class="problem-row"><td><span class="status-circle ${solved(p)?'solved':''}" aria-label="${solved(p)?'Solved':'Unsolved'}">${solved(p)?icon('check',11):''}</span></td><td><button class="problem-title" data-problem="${p.id}"><span class="number">${String(p.id).padStart(2,'0')}.</span>${esc(p.title)}</button><div class="problem-tags">${p.tags.map(esc).join(' · ')}${diagramForProblem(p)?' · Diagram':''}</div></td><td>${difficultyBadge(p)}</td><td><span class="muted tiny">${p.minutes} min</span></td><td><button class="bookmark ${saved.bookmarks.includes(p.id)?'saved':''}" data-bookmark="${p.id}" aria-label="${saved.bookmarks.includes(p.id)?'Unsave':'Save'} ${esc(p.title)}" aria-pressed="${saved.bookmarks.includes(p.id)}">${icon('book',15)}</button></td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>${list.length} ${list.length===1?'problem':'problems'} to sharpen your thinking</span><span>Made for curious minds.</span></div>`:`<div class="empty"><h3>${view==='saved'&&!saved.bookmarks.some(id=>problems.some(p=>p.id===id))?'Keep a good problem close.':'No problems match these filters.'}</h3><p class="small">${view==='saved'&&!saved.bookmarks.some(id=>problems.some(p=>p.id===id))?'Save a problem from the library to find it here.':view==='saved'?'Your saved problems are still there. Change or clear these filters to see them.':'Try a different search, topic, difficulty, or completion status.'}</p>${view==='saved'&&!saved.bookmarks.some(id=>problems.some(p=>p.id===id))?'<button class="button primary" data-view="problems">Explore the library</button>':'<button class="button primary" data-action="clear">Clear filters</button>'}</div>`}
function libraryPage(){const n=problems.filter(solved).length,total=problems.length;shell(`<div class="page"><div class="page-heading"><div><h1>${view==='saved'?'Worth another look.':'Your next breakthrough.'}</h1><p>${view==='saved'?'Your saved problems, ready when you are.':'Build your intuition. Work through a problem. Make it click.'}</p></div><div class="button-row"><button class="button" data-action="suggest">Suggest a problem</button><button class="button" data-action="random">${icon('shuffle',17)}Pick for me</button></div></div>${diagnostics.summaryCard()}${practice.libraryCard()}${interview.summaryCard()}${challenges.summaryCard()}<div class="category-grid">${categories.map(c=>`<button class="category-card ${category===c.name?'selected':''}" data-category="${c.name}" style="--topic:${c.color};--tint:${c.tint}" aria-pressed="${category===c.name}"><span class="category-icon">${icon(c.icon,21)}</span><span class="category-name">${c.name}</span><span class="category-count">${problems.filter(p=>p.category===c.name).length} problems</span></button>`).join('')}</div><div class="content-grid"><section class="library" aria-label="Problem library"><div class="library-heading"><h2>${category==='All'?(view==='saved'?'Saved problems':'Problem library'):category}</h2><span class="pill-count" id="result-count">${filtered().length}</span>${category!=='All'?'<button class="button link tiny" data-action="clear">Clear filter</button>':''}</div><div class="library-tools"><label class="search">${icon('search',16)}<input id="search" type="search" maxlength="160" placeholder="Search problems or topics..." aria-label="Search problems" value="${esc(query)}"><span class="kbd">/</span></label><select class="select" id="difficulty" aria-label="Filter by difficulty">${['All levels','Easy','Medium','Hard'].map(x=>`<option ${x===difficulty?'selected':''}>${x}</option>`).join('')}</select><select class="select" id="sort" aria-label="Sort problems"><option value="recommended">Recommended</option><option value="difficulty" ${sort==='difficulty'?'selected':''}>Difficulty</option><option value="quick" ${sort==='quick'?'selected':''}>Quickest first</option></select></div><div class="filter-tabs" role="tablist" aria-label="Problem status">${[['all','All problems'],['unsolved','To do'],['solved','Solved']].map(([s,l])=>`<button id="status-${s}" class="filter-tab ${status===s?'active':''}" data-status="${s}" role="tab" tabindex="${status===s?0:-1}" aria-controls="table-content" aria-selected="${status===s}">${l}</button>`).join('')}</div><div id="table-content" role="tabpanel" aria-labelledby="status-${status}">${tableRows()}</div></section><aside class="right-rail">${practice.dailyCard()}<section class="rail-card"><div class="rail-heading"><h3>Your progress</h3>${icon('chart',17)}</div><div class="progress-summary"><div class="progress-ring" style="--pct:${n/total*100}%"><div class="ring-center"><strong>${n}<span style="font-size:12px;color:var(--muted);font-weight:400">/${total}</span></strong><small>SOLVED</small></div></div><div><strong>${n?'Keep it going.':'A fresh start.'}</strong><p>${n?'One concept at a time.':'Your first solve awaits.'}</p></div></div><div class="mini-bars">${['Easy','Medium','Hard'].map(d=>{const all=problems.filter(p=>p.difficulty===d),count=all.filter(solved).length;return `<div class="mini-bar"><span>${d}</span><div class="bar-track"><div class="bar-fill" style="width:${all.length?count/all.length*100:0}%"></div></div><span class="mono">${count}/${all.length}</span></div>`}).join('')}</div><div class="rail-footer">Consistency builds confidence.</div></section><section class="lab-callout">${icon('capacitor',24)}<div><h3>What happens if you change R?</h3><p>Turn the knobs. Watch the response. Connect the dots.</p><button data-view="lab">Explore the circuit lab</button></div></section></aside></div><div class="bottom-note">${icon('check',13)}${session.signedIn?'Your progress follows your account across devices.':HOSTING.externalFrontend?'Guest progress stays in this browser on this website.':'Guest progress is saved in this browser. Sign in to sync across devices.'}</div></div>`)}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('toast-visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('toast-visible'),3000)}
function problemDiagram(p){const diagram=diagramForProblem(p);return diagram?`<figure class="problem-diagram">${diagram.svg}<figcaption>${esc(diagram.caption)}</figcaption><button class="diagram-expand" data-diagram-view>Enlarge diagram</button></figure>`:''}
function resultHTML(){
 const shown=feedbackPresentation(submissionFeedback.state);if(!shown)return '';
 const checked=shown.response||{};
 return `<div class="result ${shown.kind==='error'?'error':shown.kind==='success'?'':shown.kind}" role="status" aria-live="polite"><strong>${shown.kind==='pending'?icon('clock',15):''}${esc(shown.title)}</strong><p>${esc(shown.message)}</p>${shown.previous&&checked.pass!==undefined?`<p class="previous-outcome">Earlier answer: ${checked.pass?'accepted':'not accepted'}${submissionFeedback.state.runOnly?' in the test run':''}.</p>`:''}${checked.parts?`<ul class="result-parts">${checked.parts.map(part=>`<li><strong>${esc(activeProblem?.parts?.find(x=>x.id===part.id)?.label||part.id)}: ${part.pass?'Correct':'Review'}</strong><br>${esc(part.feedback)}</li>`).join('')}</ul>`:''}${checked.rows?`<div class="feedback-table-wrap"><table aria-label="HDL truth table results"><thead><tr>${(checked.inputs||[]).map(i=>`<th>${esc(i)}</th>`).join('')}<th>Expected</th><th>Your y</th><th>Result</th></tr></thead><tbody>${checked.rows.map(r=>`<tr>${(checked.inputs||[]).map(i=>`<td>${esc(r[i])}</td>`).join('')}<td>${esc(r.expected)}</td><td>${esc(r.actual)}</td><td>${r.pass?'Pass':'Fail'}</td></tr>`).join('')}</tbody></table></div>`:''}</div>`;
}
function currentSelection(){
 const selection=problemSelection({problems,progress:saved,filters:libraryFilters(),from:libraryFrom,problemId:activeProblem?.id,recommend:list=>practice.recommended(list)});
 const rank=new Map(problemOrder.map((id,index)=>[id,index]));
 return selection.sort((a,b)=>(rank.get(a.id)??Infinity)-(rank.get(b.id)??Infinity)||a.id-b.id);
}
function problemNavigation(){const p=activeProblem,selection=currentSelection(),position=selection.findIndex(item=>item.id===p.id);return `<div class="workspace-header" data-workspace-navigation><button class="button" data-action="back">${icon('grid',15)}${libraryFrom==='saved'?'Saved problems':'Problem library'}</button><span class="small muted">Make the reasoning your own.</span><div style="display:flex;gap:8px"><button class="icon-button" data-action="previous" aria-label="Previous problem" ${position<=0?'disabled':''}>${icon('left',18)}</button><span class="small muted" style="align-self:center">${position>=0?`${position+1} / ${selection.length}`:'Outside current filters'}</span><button class="icon-button" data-action="next" aria-label="Next problem" ${position<0||position===selection.length-1?'disabled':''}>${icon('chevron',18)}</button>${referenceDrawer.buttonMarkup()}<button class="icon-button bookmark ${saved.bookmarks.includes(p.id)?'saved':''}" data-bookmark="${p.id}" aria-label="${saved.bookmarks.includes(p.id)?'Unsave':'Save'} problem">${icon('book',18)}</button></div></div>`;}
function refreshProblemNavigation(){if(!activeProblem)return;const region=document.querySelector('[data-workspace-navigation]');if(region)region.outerHTML=problemNavigation();const mark=document.querySelector('[data-problem-solved]');if(mark)mark.hidden=!solved(activeProblem);}
function problemPage(){const p=activeProblem;let description=`<span class="eyebrow muted">PROBLEM ${String(p.id).padStart(2,'0')} / ${p.category}</span><h1>${esc(p.title)}</h1><div class="problem-meta">${difficultyBadge(p)}<span class="small muted" style="display:flex;align-items:center;gap:5px">${icon('clock',14)}${p.minutes} min</span><span class="small" data-problem-solved style="color:var(--green)" ${solved(p)?'':'hidden'}>✓ Solved</span></div>`;if(tab==='description')description+=`<p>${esc(p.prompt)}</p>${problemDiagram(p)}<div class="given-grid">${p.given.map(g=>`<div class="given"><small>${esc(g.label)}</small><strong>${esc(g.value)}</strong></div>`).join('')}</div><div class="task-box">${esc(p.task)}</div><div class="problem-lab-link"><p>Explore this topic with adjustable components. Lab values are separate from this question.</p><button class="button" data-sim-open="topic">${icon('bolt',15)}Open interactive lab</button></div>`;if(tab==='hints')description+=`<p>A nudge in the right direction. Open one hint at a time.</p>${(p.hints||[]).map((h,i)=>`<details class="hint-item"><summary>Hint ${i+1}</summary><p>${esc(h)}</p></details>`).join('')}`;if(tab==='solution')description+=walkthrough.markup(p)+editorial.markup(p);
description+=learning.referenceCard(p);
let answer='';const draft=saved.drafts[p.id]||'';if(p.type==='multipart'){let parts={};try{parts=JSON.parse(draft)||{};}catch{}answer=`<div class="multipart-fields">${p.parts.map(part=>`<label class="answer-label" for="answer-${esc(part.id)}">${esc(part.label)}</label><div class="answer-input"><input id="answer-${esc(part.id)}" data-answer-part="${esc(part.id)}" maxlength="200" autocomplete="off" placeholder="Value, units, or expression" value="${esc(parts[part.id]||'')}"><span>${esc(part.unit)}</span></div>`).join('')}</div><p class="hint-text">Each part earns feedback. All parts must pass to mark this problem solved. Include units or use the units shown.</p>`;}if(p.type==='numeric')answer=`<label class="answer-label" for="answer">Your answer</label><div class="answer-input"><input id="answer" maxlength="2500" name="answer" type="text" inputmode="decimal" autocomplete="off" placeholder="Enter a value" value="${esc(draft)}"><span>${esc(p.unit)}</span></div><p class="hint-text">Use ${esc(p.unit)}, equivalent units, or an expression. Accepted tolerance: ±${p.tolerance} ${esc(p.unit)}.</p>`;if(p.type==='choice')answer=`<div class="answer-label">Choose your answer</div>${p.options.map((o,i)=>`<label class="choice"><input type="radio" name="choice" value="${i}" ${draft===String(i)?'checked':''}><span>${esc(o)}</span></label>`).join('')}<div style="height:12px"></div>`;if(p.type==='hdl')answer=`<label class="answer-label" for="hdl">Verilog · continuous assignment</label><textarea id="hdl" maxlength="2500" class="code-editor" spellcheck="false" autocomplete="off" aria-label="Verilog code editor">${esc(draft||'assign y = 0;')}</textarea><p class="code-description">One-bit, 0/1 truth-table checker. Supports ~ ! & ^ | && || == != and ?: . No module declarations, timing, or X/Z simulation.</p>`;
shell(`<div id="practice-context">${practice.contextBanner(p)}</div>${problemNavigation()}<div class="workspace-layout"><section class="problem-panel"><div class="panel-tabs" role="tablist" aria-label="Problem information">${[['description','Description'],['hints','Hints'],['solution','Solution']].map(([id,l])=>`<button id="problem-tab-${id}" class="filter-tab ${tab===id?'active':''}" role="tab" tabindex="${tab===id?0:-1}" aria-controls="problem-information" aria-selected="${tab===id}" data-tab="${id}">${l}</button>`).join('')}</div><div id="problem-information" class="problem-content" role="tabpanel" aria-labelledby="problem-tab-${tab}">${description}<div class="problem-report-link"><span class="small muted">Something could be clearer?</span><button class="button link small" data-action="report">Report an issue</button></div></div></section><section class="work-panel"><form class="work-card" id="answer-form"><div class="work-card-head"><h3>${p.type==='hdl'?'Code workbench':'Your workbench'}</h3><span class="tiny muted">${p.type==='hdl'?'Combinational logic':'Think · solve · check'}</span></div><div class="work-body">${answer}<div class="button-row"><button class="button" type="button" data-action="${p.type==='hdl'?'run':'hint'}">${icon(p.type==='hdl'?'play':'bulb',15)}${p.type==='hdl'?'Run tests':'Need a hint?'}</button><button class="button primary" type="submit" ${submissionFeedback.busy?'disabled':''}>${icon('check',16)}${submissionFeedback.busy?'Checking…':'Submit answer'}</button></div><div id="feedback">${resultHTML()}</div></div></form><section class="work-card"><div class="work-card-head"><h3>Scratchpad</h3><span class="tiny muted">Just for you</span></div><textarea id="scratchpad" maxlength="10000" class="scratchpad" aria-label="Scratchpad" placeholder="Start with what you know.&#10;&#10;Write equations, sketch your reasoning...">${esc(saved.notes[p.id]||'')}</textarea><div class="scratch-footer" data-sync-status>${esc(practiceSyncText())}</div></section>${p.category==='RC circuits'?`<div class="lab-callout">${icon('capacitor',24)}<div><h3>See the transient in action.</h3><p>Explore charging and discharging with adjustable components.</p><button data-view="lab">Open the circuit lab</button></div></div>`:''}</section></div>`);}
function progressPage(){const attempts=session.signedIn?saved.attemptCount:saved.attempts.length,correct=session.signedIn?saved.acceptedCount:saved.attempts.filter(a=>a.pass).length;const solvedIds=new Set(saved.solved);shell(`<div class="page"><div class="page-heading"><div><h1>Every solve adds up.</h1><p>Your practice, at a glance. ${session.signedIn?'Synced with your account.':'Saved in this browser.'}</p></div><button class="button primary" data-action="random">${icon('play',16)}Keep practicing</button></div><div class="progress-top"><div class="stat-card"><p>Problems solved</p><strong>${problems.filter(solved).length}<span class="muted" style="font-size:18px;font-weight:400"> / ${problems.length}</span></strong><p>Concepts put into practice</p></div><div class="stat-card"><p>Total submissions</p><strong>${attempts}</strong><p>Every attempt is a step forward</p></div><div class="stat-card"><p>Accepted submissions</p><strong>${attempts?Math.round(correct/attempts*100)+'%':'—'}</strong><p>${correct} accepted of ${attempts} submissions</p></div></div>${insights.summaryCard()}<div class="progress-topics">${categories.map(c=>{const list=problems.filter(p=>p.category===c.name),n=list.filter(p=>solvedIds.has(p.id)).length;return `<section class="topic-progress"><div class="rail-heading"><div style="display:flex;align-items:center;gap:12px;color:${c.color}">${icon(c.icon,22)}<h3 style="color:var(--text)">${c.name}</h3></div><span class="small mono muted">${n} / ${list.length}</span></div><div class="bar-track"><div class="bar-fill" style="width:${n/list.length*100}%;background:${c.color}"></div></div><div class="rail-heading"><p>${n===list.length?'Topic complete. Nicely done.':`${list.length-n} problems to explore`}</p><button class="button link small" data-category="${c.name}">Practice</button></div></section>`}).join('')}</div>${attempts?`<section class="rail-card" style="margin-top:25px"><h2 style="font-size:18px">Recent submissions</h2><table class="problem-table"><tbody>${saved.attempts.slice(-8).reverse().map(a=>{const p=problems.find(p=>p.id===a.id);return `<tr><td style="width:auto">${a.pass?'<span style="color:var(--green)">Accepted</span>':'Try again'}</td><td><button class="problem-title" data-problem="${a.id}">${esc(p?.title||'Problem')}</button><span class="tiny muted">${a.source==='imported'?'Imported browser history · ':''}${esc(assistanceLabel(a.assistance))}</span></td><td class="muted tiny">${new Date(a.at).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</td></tr>`}).join('')}</tbody></table></section>`:''}</div>`)}
