const interview=createInterview({shell,esc,icon,getProblems:()=>problems,getProgress:()=>saved,storage:interviewStore,gradeAnswer:gradeInterviewAnswer,openProblem,navigate,diagramForProblem,isActive:()=>view==='interview'&&!activeProblem,toast});
interview.restore();
