const feedback=createFeedback({shell,esc,api,handoffOrigin:HOSTING.externalFrontend?HOSTING.apiOrigin:null,getSession:()=>session,toast,isActive:()=>canManage()&&view==='reports'&&!activeProblem,editProblem:async id=>{if(navigate('admin'))await admin.editProblem(id)}});
const simulations=createSimulations({shell,icon,esc,isActive:()=>view==='lab'&&!activeProblem,getProblems:()=>problems,openProblem});
const account=createAccount({externalFrontend:HOSTING.externalFrontend,accountError,shell,esc,icon,getSession:()=>session,getStore:()=>learner,getGuest:()=>guest,getGuestPending:()=>guestStore.hasPending,auth,api,beforeAuth:async({reauth=false}={})=>{if(fullHDL.hasUnsavedDraft||challenges.hasPending||community.hasPending)throw new Error('Save your module draft, finish the current submission, or clear discussion drafts before changing sign-in.');fullHDL.stop();circuitBuilder.stop();guest=guestStore.flush();await learner.flush();await interviewStore.flush();await Promise.all(labStores.map(store=>store.flush()));if(labStores.some(store=>store.hasPending&&!(reauth&&store.status.authLost))||guestStore.hasPending||(interviewStore.hasPending&&!(reauth&&interviewStore.status.authLost))||(learner.hasPending&&!(reauth&&learner.status.authLost)))throw new Error('Save or resolve pending progress changes before changing your sign-in.');},afterAuth:async()=>{if(learner.hasPending||interviewStore.hasPending||labStores.some(store=>store.hasPending)){const current=await api('/api/session');await learner.resumeAuth(current);await interviewStore.resumeAuth(current);await Promise.all(labStores.map(store=>store.resumeAuth(current)));interview.restore();debugging.restore();design.restore();diagnostics.restore();engineeringCases.restore();circuitBuilder.restore();fullHDL.restore();session=current;render();return;}location.href=auth?.accountPath||(HOSTING.externalFrontend?'/ohm/#account':'/#account');location.reload();},problems:()=>problems,toast,render:()=>{if(view==='account'&&!activeProblem)render();}});
const referenceDrawer=createReferenceDrawer({esc,icon,getProblem:()=>activeProblem,toast});
async function accountAPI(path,options={}){
 const accountId=session.signedIn?session.user?.id:null;
 if(!accountId||learner.status.authLost)throw new Error('Sign in to your practice account before continuing.');
 const result=await api(path,{...options,headers:{...options.headers,'X-Ohm-Account-ID':accountId,'X-CSRF-Token':session.csrfToken}});
 if(learner.status.authLost||!session.signedIn||session.user?.id!==accountId||result.accountId!==accountId)throw new Error('Your sign-in changed. Reload before continuing.');
 return result;
}
